#pragma material(ShadingModel = "Unlit")
/// @sort 32
uniform float A = 1.0;
// Section names in any case, with and without `=`, with and without a closing `;`.
/// @name M_LpSections
export void M_LpSections(inout material Base)
{
    float Value = 0;
    Value = A;
    Base.Opacity = Value;
}
